fn try_send_wayland_event(event_tx: &crossbeam_channel::Sender<EventMsg>, msg: EventMsg) {
    match event_tx.try_send(msg) {
        Ok(()) | Err(TrySendError::Full(_)) | Err(TrySendError::Disconnected(_)) => {}
    }
}

fn push_input_blocking(&self, event: InputEvent) {
    let mut msg = EventMsg::InputEvent(event);
    loop {
        match self.event_tx.try_send(msg) {
            Ok(()) | Err(TrySendError::Disconnected(_)) => break,
            Err(TrySendError::Full(returned_msg)) => {
                msg = returned_msg;
            }
        }

        if self.stop.load(Ordering::Relaxed) {
            break;
        }

        if self.log_enabled {
            eprintln!("event channel full, waiting to send");
        }

        match self.event_tx.send_timeout(msg, Duration::from_millis(10)) {
            Ok(()) => break,
            Err(SendTimeoutError::Timeout(returned_msg)) => {
                msg = returned_msg;
            }
            Err(SendTimeoutError::Disconnected(_)) => break,
        }
    }
}

fn handle_input_event(&mut self, event: InputEvent, tree_tx: &dyn TreeSink, log_render: bool) {
    let event = event.normalize_scroll_with_line_pixels(self.scroll_line_pixels);
    let label = input_event_label(&event);
    self.log_event_diagnostic(log_render, || {
        format!(
            "input begin\n  event: {label}\n  {}",
            self.diagnostic_summary(),
        )
    });
    self.record_pointer_snapshot(&event);
    self.cancel_inertial_scroll_for_input(&event);
    crate::debug_trace::hover_trace!(
        "event_input",
        "event={:?} stale={} buffered={}",
        event,
        self.listener_lane.is_stale(),
        self.listener_lane.buffered_inputs.len()
    );
    forward_observer_input(
        &event,
        &self.input_handler,
        &self.input_target,
        self.host_event_sink.as_deref(),
    );
    self.clear_text_commit_suppressions_for_event(&event);

    if self.listener_lane.is_stale() {
        let buffered_before = self.listener_lane.buffered_inputs.len();
        self.listener_lane.buffer_input(event);
        self.log_event_diagnostic(log_render, || {
            format!(
                "input buffered while listener lane stale\n  event: {label}\n  buffered_before: {buffered_before}\n  buffered_after: {}\n  {}",
                self.listener_lane.buffered_inputs.len(),
                self.diagnostic_summary(),
            )
        });
        return;
    }

    self.dispatch_event(event, tree_tx, log_render, DispatchMode::Normal);
    self.log_event_diagnostic(log_render, || {
        format!(
            "input end\n  event: {label}\n  {}",
            self.diagnostic_summary(),
        )
    });
}

fn dispatch<R>(
    &mut self,
    operation: impl FnOnce(&mut DirectEventRuntime, &dyn TreeSink, bool) -> R,
) -> R {
    let commands = EventCommands::default();
    let result = operation(&mut self.runtime, &commands, self.log_render);
    let mut messages = commands.0.into_inner();
    if std::mem::take(&mut self.runtime.listener_lane.needs_barrier) {
        let barrier = crate::actors::ListenerBarrier::default();
        self.awaiting_registry = Some(barrier.clone());
        messages.push(TreeMsg::ListenerBarrier(barrier));
    }
    if !messages.is_empty() {
        let mut targets: Vec<_> = messages.iter().filter_map(TreeMsg::target_id).collect();
        targets.sort_unstable_by_key(|id| id.0);
        targets.dedup();
        let packet = if targets.is_empty() {
            TreeMsg::Batch(messages)
        } else {
            TreeMsg::EventBatch {
                target_mounts: targets
                    .into_iter()
                    .map(|id| (id, self.runtime.base_registry.source_mount(&id)))
                    .collect(),
                messages,
            }
        };
        self.queue_tree_packet(packet);
    }
    result
}

fn queue_tree_packet(&mut self, packet: TreeMsg) {
    // Once a packet is deferred, new operations must not overtake it even
    // when a slot happens to become available during this dispatch.
    if self.outbox.is_empty() {
        match self.tree_tx.try_send(packet) {
            Ok(()) => {}
            Err(TrySendError::Full(packet) | TrySendError::Disconnected(packet)) => {
                self.outbox.push_back(packet)
            }
        }
    } else {
        self.outbox.push_back(packet);
    }
}

fn read_frame(stream: &mut UnixStream) -> io::Result<Vec<u8>> {
    let mut len_buf = [0_u8; 4];
    stream.read_exact(&mut len_buf)?;
    let len = u32::from_be_bytes(len_buf) as usize;
    let mut payload = vec![0_u8; len];
    stream.read_exact(&mut payload)?;
    Ok(payload)
}

pub(crate) fn send_input_event(pid: LocalPid, event: &InputEvent) {
    let mut env = OwnedEnv::new();
    let _ = env.send_and_clear(&pid, |inner_env| {
        (emerge_skia_event(), event).encode(inner_env)
    });
}
